import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage } from '../../utils/helpers';
import { OPERATING_REGIONS } from '../../utils/constants';

const VendorList = () => {
  const [vendors, setVendors] = useState([]);
  const [filteredVendors, setFilteredVendors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filters, setFilters] = useState({
    region: '',
    cuisine: '',
    search: ''
  });

  useEffect(() => {
    loadVendors();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [vendors, filters]);

  const loadVendors = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await vendorService.getAllPublicVendors();
      setVendors(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...vendors];

    // Filter by region
    if (filters.region) {
      filtered = filtered.filter(vendor => 
        vendor.operatingRegion && vendor.operatingRegion.toLowerCase() === filters.region.toLowerCase()
      );
    }

    // Filter by cuisine
    if (filters.cuisine) {
      filtered = filtered.filter(vendor =>
        vendor.cuisineSpecialties && 
        vendor.cuisineSpecialties.toLowerCase().includes(filters.cuisine.toLowerCase())
      );
    }

    // Filter by search term (name, cuisine, or menu highlights)
    if (filters.search) {
      const searchTerm = filters.search.toLowerCase();
      filtered = filtered.filter(vendor =>
        (vendor.name && vendor.name.toLowerCase().includes(searchTerm)) ||
        (vendor.cuisineSpecialties && vendor.cuisineSpecialties.toLowerCase().includes(searchTerm)) ||
        (vendor.menuHighlights && vendor.menuHighlights.toLowerCase().includes(searchTerm))
      );
    }

    setFilteredVendors(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      region: '',
      cuisine: '',
      search: ''
    });
  };

  const getUniqueCuisines = () => {
    const cuisines = vendors.map(vendor => vendor.cuisineSpecialties)
      .filter(cuisine => cuisine)
      .flatMap(cuisine => cuisine.split(',').map(c => c.trim()))
      .filter((cuisine, index, array) => array.indexOf(cuisine) === index)
      .sort();
    return cuisines;
  };

  if (loading) {
    return <LoadingSpinner message="Loading food trucks..." />;
  }

  return (
    <div className="vendor-list-page">
      <div className="container">
        <div className="page-header">
          <h1>Find Food Trucks</h1>
          <p>Discover amazing food trucks in Chennai and Bangalore</p>
        </div>

        {error ? (
          <div className="error-container">
            <div className="error-message">
              <p>{error}</p>
              <button onClick={loadVendors} className="btn btn-primary">
                Try Again
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Filters */}
            <div className="filters-section">
              <div className="filters-row">
                <div className="filter-group">
                  <label htmlFor="search">Search</label>
                  <input
                    type="text"
                    id="search"
                    placeholder="Search by name, cuisine, or specialty..."
                    value={filters.search}
                    onChange={(e) => handleFilterChange('search', e.target.value)}
                  />
                </div>

                <div className="filter-group">
                  <label htmlFor="region">Region</label>
                  <select
                    id="region"
                    value={filters.region}
                    onChange={(e) => handleFilterChange('region', e.target.value)}
                  >
                    <option value="">All Regions</option>
                    {OPERATING_REGIONS.map(region => (
                      <option key={region} value={region}>{region}</option>
                    ))}
                  </select>
                </div>

                <div className="filter-group">
                  <label htmlFor="cuisine">Cuisine</label>
                  <select
                    id="cuisine"
                    value={filters.cuisine}
                    onChange={(e) => handleFilterChange('cuisine', e.target.value)}
                  >
                    <option value="">All Cuisines</option>
                    {getUniqueCuisines().map(cuisine => (
                      <option key={cuisine} value={cuisine}>{cuisine}</option>
                    ))}
                  </select>
                </div>

                <div className="filter-actions">
                  <button onClick={clearFilters} className="btn btn-outline">
                    Clear Filters
                  </button>
                </div>
              </div>
            </div>

            {/* Results Summary */}
            <div className="results-summary">
              <p>
                Showing {filteredVendors.length} of {vendors.length} food trucks
              </p>
            </div>

            {/* Vendors Grid */}
            {filteredVendors.length > 0 ? (
              <div className="vendors-grid">
                {filteredVendors.map((vendor) => (
                  <div key={vendor.id} className="vendor-card">
                    <div className="vendor-info">
                      <h3>{vendor.name}</h3>
                      <p className="cuisine">{vendor.cuisineSpecialties}</p>
                      <p className="region">📍 {vendor.operatingRegion}</p>
                      
                      {vendor.menuHighlights && (
                        <div className="menu-highlights">
                          <h4>Menu Highlights</h4>
                          <p>{vendor.menuHighlights}</p>
                        </div>
                      )}

                      {vendor.businessAddress && (
                        <p className="address">📍 {vendor.businessAddress}</p>
                      )}

                      {vendor.phoneNumber && (
                        <p className="phone">📞 {vendor.phoneNumber}</p>
                      )}
                    </div>

                    <div className="vendor-actions">
                      <Link to={`/vendor/${vendor.id}`} className="btn btn-primary">
                        View Details
                      </Link>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-results">
                <h3>No food trucks found</h3>
                <p>Try adjusting your filters or search terms.</p>
                <button onClick={clearFilters} className="btn btn-primary">
                  Clear All Filters
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default VendorList;
